/* V30 PHYSICAL BUTTON CORRECTION — owner screenshot 2026-11-02.
   UI research: Dan Andersson's 3D Buttons CodePen (praktikdan/jbqBWm),
   based on Mikael Eidenberg's synth-button concept. Adapted material and
   raised-vs-recessed behavior for small mixer strips, not the demo's
   mutually exclusive jQuery toggle. Original on/off model is unchanged.

   Core correction from V29: a #333 key ON dark #142832 chassis was too close
   in luminance to its bezel; remove tiny black-on-black keycap and glowing
   text illusion. Brighter GRAPHITE SATIN cap rests physically ABOVE a static
   dark switchplate; latched buttons sit INSIDE the same opening. Narrow
   LED seams are IN the depressed face — no diffuse shadow or filter. */

/* One stationary shared key well for all three MUTE/SOLO/PFL caps. This
   plate and each .hw-switch-socket's overlaid lip NEVER move on click. */
.console-body .strip .switch-section{
 background:#0b1a22!important;
 border-top:1px solid #040e14!important;
 border-bottom:1px solid #415764!important;
 box-shadow:inset 0 1px #02090d,inset 0 -1px #2c424e!important;
}
.console-body .strip .switch-section .hw-switch-socket{
 background:#061118!important;
 border:1px solid #050b0f!important;
 border-radius:3px!important;
 box-shadow:inset 0 1px 0 #000,inset 1px 0 0 #000,
            inset -1px 0 0 #425965,inset 0 -1px 0 #435a64!important;
 transform:none!important;
}
.console-body .strip .switch-section .hw-switch-socket::before{
 background:linear-gradient(180deg,#030a10,#142630)!important;
 z-index:0!important;
}
.console-body .strip .switch-section .hw-switch-socket::after{
 z-index:4!important;
 pointer-events:none!important;
 border-radius:3px!important;
 box-shadow:inset 0 1px 0 #b1cdd43b,inset 1px 0 0 #9cb9c32f,
            inset -1px 0 0 #000e,inset 0 -1px 0 #050b10!important;
}
/* This one shared satin-material token also styles toolbar and ordinary
   rectangular push controls, but never faders, sockets for patch cables,
   VU meter or pan thumb. No layered waves or bright-dark-bright cycles. */
:is(
 .command-bar button.tool,.command-bar summary.tool,.more-tools-panel button.tool,
 .console-body .strip .switch-section .hw-switch-socket>.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key
){
 --am-key30-led:#6acadd;
 position:relative!important;
 z-index:2!important;
 box-sizing:border-box!important;
 border:1px solid #7b929d!important;
 border-top-color:#b4c7cf!important;
 border-right-color:#263842!important;
 border-bottom-color:#1a282f!important;
 border-radius:2px!important;
 background:linear-gradient(180deg,var(--am-key30-top) 0%,var(--am-key30-bottom) 100%)!important;
 color:#f3f8fa!important;
 text-shadow:0 -1px 0 #0e1c24!important;
 box-shadow:inset 1px 0 0 #d6eff92f,inset 0 1px 0 #ffffff31,
            0 1px 0 #17252d,0 2px 0 #060c10!important;
 transform:translateY(0)!important;
 filter:none!important;backdrop-filter:none!important;
 -webkit-backdrop-filter:none!important;
 transition:none!important;
}
:is(
 .command-bar button.tool,.command-bar summary.tool,.more-tools-panel button.tool,
 .console-body .strip .switch-section .hw-switch-socket>.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key
)::before{
 content:""!important;display:block!important;position:absolute!important;
 left:2px!important;right:2px!important;top:0!important;bottom:auto!important;
 width:auto!important;height:2px!important;
 background:var(--am-key30-hairline)!important;
 border:0!important;box-shadow:none!important;pointer-events:none!important;
}
:is(
 .command-bar button.tool,.command-bar summary.tool,.more-tools-panel button.tool,
 .console-body .strip .switch-section .hw-switch-socket>.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key
)::after{
 content:""!important;display:block!important;position:absolute!important;
 left:2px!important;right:2px!important;bottom:0!important;top:auto!important;
 width:auto!important;height:1px!important;
 background:var(--am-key30-lowline)!important;
 border:0!important;box-shadow:none!important;pointer-events:none!important;
}
:is(
 .command-bar button.tool,.command-bar summary.tool,.more-tools-panel button.tool,
 .console-body .strip .switch-section .hw-switch-socket>.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key
):hover:not(:disabled):not(.on):not(.active):not([aria-pressed="true"]):not([aria-expanded="true"]){
 background:linear-gradient(180deg,var(--am-key30-hover-top),var(--am-key30-hover-bottom))!important;
 box-shadow:inset 1px 0 0 #e6f5fa36,inset 0 1px 0 #ffffff39,
            0 1px 0 #17252d,0 2px 0 #060c10!important;
}
/* One color-variable controls the pair of LED seams; keep label readable
   even when no accent LED is illuminated. Never use text-shadow glow. */
:is(
 .console-body .strip .switch-section .hw-switch-socket>.switch.on,
 .command-bar button.tool.active,.command-bar button.tool[aria-pressed="true"],
 .command-bar summary.tool[aria-expanded="true"],
 .more-tools[open] summary.tool,.more-tools-panel button.tool.active,
 button.hw-key[aria-pressed="true"]
){
 --am-key30-led:#6acadd;
 background:linear-gradient(180deg,var(--am-key30-down-top),var(--am-key30-down-bottom))!important;
 border:1px solid #09151b!important;
 border-top-color:#0a1319!important;
 border-left-color:#08121a!important;
 border-right-color:#081219!important;
 border-bottom-color:#263944!important;
 color:#edf8fb!important;
 box-shadow:inset 0 2px 1px #000b,inset 1px 0 0 #eaf6ff0d,
            inset 0 -1px 0 #b8d8e328!important;
 text-shadow:0 1px 0 #000!important;
 transform:translateY(1px)!important;
}
:is(
 .console-body .strip .switch-section .hw-switch-socket>.switch.on,
 .command-bar button.tool.active,.command-bar button.tool[aria-pressed="true"],
 .command-bar summary.tool[aria-expanded="true"],
 .more-tools[open] summary.tool,.more-tools-panel button.tool.active,
 button.hw-key[aria-pressed="true"]
)::before{
 left:0!important;right:auto!important;top:3px!important;bottom:3px!important;
 width:2px!important;height:auto!important;
 background:linear-gradient(180deg,transparent,var(--am-key30-led) 38%,
      var(--am-key30-led) 62%,transparent)!important;
}
:is(
 .console-body .strip .switch-section .hw-switch-socket>.switch.on,
 .command-bar button.tool.active,.command-bar button.tool[aria-pressed="true"],
 .command-bar summary.tool[aria-expanded="true"],
 .more-tools[open] summary.tool,.more-tools-panel button.tool.active,
 button.hw-key[aria-pressed="true"]
)::after{
 left:auto!important;right:0!important;top:3px!important;bottom:3px!important;
 width:2px!important;height:auto!important;
 background:linear-gradient(180deg,transparent,var(--am-key30-led) 38%,
      var(--am-key30-led) 62%,transparent)!important;
}
.console-body .strip .switch-section .hw-switch-socket>.switch.on.mute{
 --am-key30-led:#ef6376;color:#ffe9ed!important;
}
.console-body .strip .switch-section .hw-switch-socket>.switch.on.solo{
 --am-key30-led:#f6d16b;color:#fff0c0!important;
}
.console-body .strip .switch-section .hw-switch-socket>.switch.on.cue{
 --am-key30-led:#78d3e9;color:#dffaff!important;
}
:is(
 .command-bar button.tool,.command-bar summary.tool,.more-tools-panel button.tool,
 .console-body .strip .switch-section .hw-switch-socket>.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key
):active:not(:disabled){
 transform:translateY(1px)!important;
 box-shadow:inset 0 2px 1px #000a,inset 0 -1px 0 #cce5f116!important;
}
:is(
 .command-bar button.tool,.command-bar summary.tool,.more-tools-panel button.tool,
 .console-body .strip .switch-section .hw-switch-socket>.switch,
 .identity-actions button.console-control,.plugin-footer button,
 .route-choice-head button,.route-choice-option,button.hw-key
):focus-visible{outline:2px solid #80d5ed!important;outline-offset:2px!important}
.command-bar{align-items:center!important;gap:5px!important}
.command-bar .tool,.command-bar .toolbar-select{white-space:nowrap;text-overflow:ellipsis}
.command-bar .toolbar-label{letter-spacing:.04em}
@media(max-width:1400px){.command-bar{gap:3px!important}.command-bar .tool{padding-inline:6px!important}}
@media(prefers-reduced-motion:reduce){
 .console-body.wire-routing-v15 .strip .wire-tray .wire-pot::before{transition:none!important}
}
@media(max-width:1000px){.mixer-title .wire-v34-tool{min-width:30px;padding:0 3px!important}.wire-workspace{right:3px}}
